CREATE INDEX invoices_user_id_due_date_idx ON public.invoices USING btree (user_id, due_date);
CREATE INDEX invoices_user_id_status_idx ON public.invoices USING btree (user_id, status);
CREATE INDEX invoice_items_invoice_id_idx ON public.invoice_items USING btree (invoice_id);
CREATE INDEX idx_paychecks_date ON public.paychecks USING btree (user_id, pay_date DESC);
CREATE INDEX idx_paychecks_job ON public.paychecks USING btree (job_id);
CREATE INDEX idx_paychecks_user ON public.paychecks USING btree (user_id);
CREATE INDEX idx_paycheck_invoices_invoice ON public.paycheck_invoices USING btree (invoice_id);
CREATE INDEX idx_paycheck_invoices_paycheck ON public.paycheck_invoices USING btree (paycheck_id);
CREATE INDEX idx_paycheck_taxes_paycheck ON public.paycheck_taxes USING btree (paycheck_id);
CREATE INDEX idx_paycheck_deposits_account ON public.paycheck_deposits USING btree (account_id);
CREATE INDEX idx_paycheck_deposits_paycheck ON public.paycheck_deposits USING btree (paycheck_id);
CREATE INDEX idx_union_memberships_user ON public.union_memberships USING btree (user_id);
CREATE INDEX idx_union_dues_membership ON public.union_dues_payments USING btree (membership_id);
CREATE INDEX idx_union_dues_user ON public.union_dues_payments USING btree (user_id);
CREATE INDEX idx_union_documents_shared ON public.union_documents USING btree (is_shared) WHERE (is_shared = true);
CREATE INDEX idx_union_documents_user ON public.union_documents USING btree (user_id);
CREATE INDEX idx_union_chunks_document ON public.union_document_chunks USING btree (document_id);
CREATE INDEX idx_union_chunks_embedding ON public.union_document_chunks USING ivfflat (embedding vector_cosine_ops) WITH (lists='50');
CREATE INDEX idx_rag_submissions_status ON public.union_rag_submissions USING btree (status);
CREATE INDEX idx_rag_submissions_user ON public.union_rag_submissions USING btree (user_id);
CREATE INDEX idx_contact_phones_contact ON public.contact_phones USING btree (contact_id);
CREATE INDEX idx_contact_emails_contact ON public.contact_emails USING btree (contact_id);
CREATE INDEX idx_contact_tags_contact ON public.contact_tags USING btree (contact_id);
CREATE INDEX idx_contact_tags_type_value ON public.contact_tags USING btree (tag_type, value);
CREATE INDEX idx_contact_job_roles_contact ON public.contact_job_roles USING btree (contact_id);
CREATE INDEX idx_contact_job_roles_job ON public.contact_job_roles USING btree (job_id);
CREATE INDEX idx_contact_shares_shared_by ON public.contact_shares USING btree (shared_by);
CREATE INDEX idx_contact_shares_shared_with ON public.contact_shares USING btree (shared_with, status);
CREATE INDEX idx_contact_addresses_contact ON public.contact_addresses USING btree (contact_id);
CREATE INDEX idx_contact_locations_contact ON public.contact_locations USING btree (contact_id);

COMMIT;

